INSERT INTO "psychology_methods" ("id", "name", "description", "instruction") VALUES
  (1, 'Ayzenk temperament testi', 'Shaxs temperamenti turini aniqlash uchun qisqartirilgan Ayzenk soʻrovnomasi.', '{"text": "Har bir savolga ''Ha'' yoki ''Yoʻq'' deb javob bering. Uzoq oʻylamang — birinchi javob eng toʻgʻrisi.", "scoring": {"method": "category", "reverse": [], "categories": {"Ekstraversiya": [], "Neyrotizm": []}}, "category_interpretations": {"Ekstraversiya": [{"min": 0, "max": 3, "label": "Introvert", "description": "Yopiq, oʻz ichki dunyosiga yoʻnaltirilgan."}, {"min": 4, "max": 7, "label": "Ambivert", "description": "Muvozanatli, vaziyatga qarab moslashuvchan."}, {"min": 8, "max": 12, "label": "Ekstravert", "description": "Ochiq, muloqotchan, tashqi faoliyatga yoʻnaltirilgan."}], "Neyrotizm": [{"min": 0, "max": 3, "label": "Barqaror", "description": "Hissiy jihatdan barqaror."}, {"min": 4, "max": 7, "label": "Oʻrtacha", "description": "Stressga oʻrtacha darajada javob beradi."}, {"min": 8, "max": 12, "label": "Beqaror", "description": "Hissiy beqarorlik belgilari mavjud."}]}}'::jsonb),
  (2, 'Talaba xavotir darajasi shkalasi', 'Oʻquv jarayonidagi xavotir darajasini oʻlchovchi 8 savolli shkala.', '{"text": "Har bir holatni 1 dan 5 gacha baholang: 1 — umuman toʻgʻri emas, 5 — toʻliq toʻgʻri.", "scoring": {"method": "sum", "reverse": [7, 8]}, "interpretation": [{"min": 8, "max": 16, "label": "Past xavotir", "description": "Xavotir darajasi past, oʻquv yuklamasi qulay qabul qilinmoqda."}, {"min": 17, "max": 28, "label": "Oʻrtacha xavotir", "description": "Meʼyoriy daraja. Imtihon davrida vaqtni rejalashtirish tavsiya etiladi."}, {"min": 29, "max": 40, "label": "Yuqori xavotir", "description": "Yuqori daraja. Psixolog bilan suhbat tavsiya etiladi."}]}'::jsonb),
  (3, 'Oʻquv motivatsiyasi soʻrovnomasi', 'Talabaning oʻqishga boʻlgan ichki va tashqi motivatsiyasini baholaydi.', '{"text": "Har bir savol uchun oʻzingizga eng mos javobni tanlang.", "scoring": {"method": "sum", "reverse": []}, "interpretation": [{"min": 0, "max": 8, "label": "Past motivatsiya", "description": "Oʻquv motivatsiyasi past — tyutor bilan ishlash tavsiya etiladi."}, {"min": 9, "max": 16, "label": "Oʻrtacha motivatsiya", "description": "Motivatsiya barqaror, lekin qoʻshimcha ragʻbat foydali."}, {"min": 17, "max": 24, "label": "Yuqori motivatsiya", "description": "Kuchli ichki motivatsiya — ilmiy faoliyatga jalb etish mumkin."}]}'::jsonb);
INSERT INTO "psychology_questions" ("id", "method_id", "question_type", "content", "options", "order", "category") VALUES
  (1, 1, 'true_false', '{"text": "Sizga yangi odamlar bilan tanishish yoqadimi?"}'::jsonb, NULL, 1, 'Ekstraversiya'),
  (2, 1, 'true_false', '{"text": "Koʻp odamli tadbirlarda oʻzingizni erkin his qilasizmi?"}'::jsonb, NULL, 2, 'Ekstraversiya'),
  (3, 1, 'true_false', '{"text": "Suhbatda koʻpincha tashabbusni oʻz qoʻlingizga olasizmi?"}'::jsonb, NULL, 3, 'Ekstraversiya'),
  (4, 1, 'true_false', '{"text": "Yolgʻiz qolishdan koʻra doʻstlar davrasini afzal koʻrasizmi?"}'::jsonb, NULL, 4, 'Ekstraversiya'),
  (5, 1, 'true_false', '{"text": "Notanish auditoriya oldida gapirish sizga oson kechadimi?"}'::jsonb, NULL, 5, 'Ekstraversiya'),
  (6, 1, 'true_false', '{"text": "Rejalarni tez oʻzgartirishga tayyormisiz?"}'::jsonb, NULL, 6, 'Ekstraversiya'),
  (7, 1, 'true_false', '{"text": "Kayfiyatingiz tez-tez oʻzgaradimi?"}'::jsonb, NULL, 7, 'Neyrotizm'),
  (8, 1, 'true_false', '{"text": "Kichik muammolar ham sizni uzoq bezovta qiladimi?"}'::jsonb, NULL, 8, 'Neyrotizm'),
  (9, 1, 'true_false', '{"text": "Tunda uyquga ketish qiyin boʻladigan holatlar boʻladimi?"}'::jsonb, NULL, 9, 'Neyrotizm'),
  (10, 1, 'true_false', '{"text": "Oʻzingizni asabiy his qilasizmi?"}'::jsonb, NULL, 10, 'Neyrotizm'),
  (11, 1, 'true_false', '{"text": "Koʻpincha sababsiz xavotirlanasizmi?"}'::jsonb, NULL, 11, 'Neyrotizm'),
  (12, 1, 'true_false', '{"text": "Tanqidni ogʻir qabul qilasizmi?"}'::jsonb, NULL, 12, 'Neyrotizm'),
  (13, 2, 'scale', '{"text": "Imtihon oldidan kuchli hayajonlanaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 1, NULL),
  (14, 2, 'scale', '{"text": "Baho olishdan qoʻrqaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 2, NULL),
  (15, 2, 'scale', '{"text": "Auditoriyada javob berishda qoʻlim titraydi.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 3, NULL),
  (16, 2, 'scale', '{"text": "Yangi fan boshlanganda oʻzimni yoʻqotib qoʻyaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 4, NULL),
  (17, 2, 'scale', '{"text": "Guruhdoshlarim oldida xato qilishdan uyalaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 5, NULL),
  (18, 2, 'scale', '{"text": "Topshiriq muddati yaqinlashganda uxlay olmayman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 6, NULL),
  (19, 2, 'scale', '{"text": "Oʻquv rejasini bemalol bajara olaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 7, NULL),
  (20, 2, 'scale', '{"text": "Qiyin vaziyatda ham xotirjam qola olaman.", "min": 1, "max": 5, "min_label": "Umuman toʻgʻri emas", "max_label": "Toʻliq toʻgʻri"}'::jsonb, NULL, 8, NULL),
  (21, 3, 'text', '{"text": "Darsga tayyorgarlik koʻrishga qancha vaqt ajratasiz?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 1, NULL),
  (22, 3, 'text', '{"text": "Qoʻshimcha adabiyot oʻqiysizmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 2, NULL),
  (23, 3, 'text', '{"text": "Ilmiy toʻgaraklarda qatnashasizmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 3, NULL),
  (24, 3, 'text', '{"text": "Tanlagan yoʻnalishingiz sizga qiziqarlimi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 4, NULL),
  (25, 3, 'text', '{"text": "Kelajakda shu sohada ishlashni rejalashtiryapsizmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 5, NULL),
  (26, 3, 'text', '{"text": "Yuqori baho olish siz uchun muhimmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 6, NULL),
  (27, 3, 'text', '{"text": "Mustaqil loyihalar qilasizmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 7, NULL),
  (28, 3, 'text', '{"text": "Oʻqituvchidan qoʻshimcha savol berasizmi?"}'::jsonb, '[{"text": "Deyarli hech qachon", "value": 0}, {"text": "Baʼzan", "value": 1}, {"text": "Tez-tez", "value": 2}, {"text": "Doimo", "value": 3}]'::jsonb, 8, NULL);
